def _redirect(route):
    guard(route)
    if 'httpsRedirect' not in route:
        if 'httpsRedirect' in route.get('_coverage', {}):
            raise Unavailable('redirect field unreadable')
        return False
    return get(route, 'httpsRedirect', bool)

